catalog_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var $ = this.jQuery,
        fieldName1 = "container_employee_satisfaction_START",
        fieldName2 = "container_manager_evaluation_START",
        fieldName3 = "mvar_others_manager_evaluation",
        fieldName4 = "container_objective_or_measure_START",
		fieldName5 = "container_training_and_professional_development_START",
		fieldName6 = "container_remarks_comments_START";

    setTimeout(function() {
        var $fieldset = $("#" + fieldName1);
        if ($fieldset) {
            setTitleFormat($fieldset, '');
        }

        $fieldset = $("#" + fieldName2);
        if ($fieldset) {
            setTitleFormat($fieldset, '');
        }

        $fieldset = $("#" + fieldName3);
        if ($fieldset) {
            $fieldset[0].parentElement.style.color = 'red';
            $fieldset[0].parentElement.style.paddingTop = '5px';
            $fieldset[0].parentElement.style.paddingLeft = '37px';
        }

        $fieldset = $("#" + fieldName4);
        if ($fieldset) {
            setTitleFormat($fieldset, '15px');
        }

        $fieldset = $("#" + fieldName5);
        if ($fieldset) {
            setTitleFormat($fieldset, '10px');
        }

        $fieldset = $("#" + fieldName6);
        if ($fieldset) {
            setTitleFormat($fieldset, '10px');
        }
    });

    function setTitleFormat(refElem, pixel) {
        refElem[0].style.fontSize = '2.0rem';
        refElem[0].parentElement.style.color = 'white';
        refElem[0].parentElement.style.background = '#c31a1f';
        refElem[0].parentElement.style.padding = '5px 5px';
        if (pixel!='') {
            refElem[0].parentElement.style.marginTop = pixel;
        }
        refElem[0].parentElement.nextElementSibling.style.color = 'red';
        refElem[0].parentElement.nextElementSibling.style.paddingTop = '10px';
        refElem[0].parentElement.nextElementSibling.style.paddingLeft = '20px';
    }
}
